/* P2-E25 rtcli: research ENCODER writing a genuine CZN1 frame: production table program (rt_encode_table = pinned
 * kg_encode_table) serialized with a PER-LEAF codec policy (rt.inc, generated by gen_rt.py). Existing KG syntax and
 * leaf codecs only; decoded by the production kolmo -d.
 * usage: rtcli rt POLICY SRC DST   POLICY: bsc_nr | z12_nr | mix32 | mix128 | mix32_z19 | mix128_z19 | mix32_r */
#include "../P2-E11/p2e11.c"
static size_t rt_K = 32768; static int rt_bc = C_BSC, rt_bl = 0, rt_sc = C_ZSTD, rt_sl = 12, rt_rans = 0;
static int rt_leaf(int codec, int level, size_t n, int *lvl) { (void)codec; (void)level; if (n >= rt_K) { *lvl = rt_bl; return rt_bc; } *lvl = rt_sl; return rt_sc; }
#include "rt.inc"
__attribute__((constructor)) static void rt(int argc, char **argv, char **envp) {
    (void)envp; if (argc < 5 || strcmp(argv[1], "rt")) return;
    for (int c = 0; c < NC; c++) CONF[c] = -1;
    const char *p = argv[2];
    if (!strcmp(p, "bsc_nr")) rt_K = 0;
    else if (!strcmp(p, "z12_nr")) rt_K = (size_t)-1;
    else if (!strcmp(p, "mix32")) rt_K = 32768;
    else if (!strcmp(p, "mix128")) rt_K = 131072;
    else if (!strcmp(p, "mix32_z19")) { rt_K = 32768; rt_sl = 19; }
    else if (!strcmp(p, "mix128_z19")) { rt_K = 131072; rt_sl = 19; }
    else if (!strcmp(p, "mix32_r")) { rt_K = 32768; rt_rans = 1; }
    else DIE("rtcli: unknown policy %s", p);
    size_t n; uint8_t *src = readfile(argv[3], &n); if (!src || !n) DIE("rtcli: read");
    kolmo_params kp = {KOLMO_FAST, 0, 1, 0, 0}; size_t cap = kolmo_bound(n, &kp) + n / 8 + 65536;
    uint8_t *f = malloc(cap), *tmp = malloc(cap); size_t fn = 0; codec_ctx x = {0};
    size_t pn = n >= 64 ? rt_encode_table(&x, C_BSC, 0, src, n, ',', '.', tmp, cap) : 0;   /* C_BSC = "slow" analysis path */
    if (pn) { fn = tp_wrap(src, n, 0, 0, tmp, pn, f); f[HDR + IDX + 1] = ','; f[HDR + IDX + 2] = '.';
              uint32_t hc = kolmo_crc32c(0, f, 28); hc = kolmo_crc32c(hc, f + HDR, IDX); put32(f + 28, hc); }
    if (!fn) fn = tp_fallback(src, n, f, cap);
    if (!fn) DIE("rtcli: encode failed");
    FILE *o = fopen(argv[4], "wb"); if (!o || fwrite(f, 1, fn, o) != fn || fclose(o)) DIE("rtcli: write");
    codec_ctx_free(&x); free(tmp); free(f); free(src); exit(0);
}
